#include <sgl.h>

/**
 * Cover flow demo: a stacked horizontal sliding menu made of rounded
 * rectangles (rect_ext widget).
 *
 * The centered card stays on the top layer and is drawn largest, the
 * cards beside it shrink progressively. Drag left / right with the mouse
 * and the cards follow the finger with a live scale effect; on release
 * the menu snaps to the nearest card with an ease-out animation. Tapping
 * a side card slides it to the center; tapping the centered card needs
 * no handling.
 *
 * Keyboard: the widget lives in a key group, press ENTER once to enter
 * scroll mode, then LEFT / RIGHT scroll one card per key press and ESC
 * leaves scroll mode again.
 */

#include <stdint.h>
#include <sgl_core.h>

